return $input.all().flatMap((item, index) =>
  item.json.data.invoices.nodes.map((invoice) => ({
    json: invoice,
    pairedItem: { item: index }
  }))
);

const invoice = $json;
const total = invoice.total;
const match = typeof total === 'string' ? total.match(/^\d+\.\d{2}$/) : null;
if (!match || match[0] !== total) throw new Error('invalid_total');
const [whole, fraction] = total.split('.');
const cents = BigInt(whole) * 100n + BigInt(fraction);
if (cents > BigInt(Number.MAX_SAFE_INTEGER)) throw new Error('invalid_total');
const total_cents = Number(cents);
const date = new Date(invoice.issuedAt + 'T00:00:00Z');
if (Number.isNaN(date.getTime())) throw new Error('invalid_issued_at');
// Thursday determines the ISO week-year; UTC avoids local timezone changes.
date.setUTCDate(date.getUTCDate() + 4 - (date.getUTCDay() || 7));
const iso_year = date.getUTCFullYear();
const year_start = new Date(Date.UTC(iso_year, 0, 1));
const week = Math.ceil(((date - year_start) / 86400000 + 1) / 7);
const iso_week = String(iso_year) + '-W' + String(week).padStart(2, '0');
return { json: {
  id: invoice.id,
  client: invoice.client,
  status: invoice.status,
  total_cents,
  issued_at: invoice.issuedAt,
  iso_week
} };

return $input.all().map(({ json: { id, error } }) => ({ json: {
  id,
  reason: typeof error === 'string' ? error : (error?.message ?? String(error))
} }));

const weeks = new Map();
for (const { json: invoice } of $input.all()) {
  if (!weeks.has(invoice.iso_week)) weeks.set(invoice.iso_week, {
    iso_week: invoice.iso_week,
    revenue_paid_cents: 0,
    invoices_paid: 0,
    invoices_open: 0,
    avg_paid_cents: 0
  });
  const row = weeks.get(invoice.iso_week);
  if (invoice.status === 'paid') {
    row.revenue_paid_cents += invoice.total_cents;
    row.invoices_paid += 1;
  } else {
    row.invoices_open += 1;
  }
}
return [...weeks.values()].map((row) => ({ json: {
  ...row,
  avg_paid_cents: row.invoices_paid === 0 ? 0 :
    Math.floor(row.revenue_paid_cents / row.invoices_paid)
} }));
